import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BAQ5ZYJQ.js";const p=JSON.parse('{"title":"What errand is","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-errand.md","filePath":"guide/what-is-errand.md","lastUpdated":1795160929000}'),r={name:"guide/what-is-errand.md"};function s(i,e,d,h,c,l){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="what-errand-is" tabindex="-1">What errand is <a class="header-anchor" href="#what-errand-is" aria-label="Permalink to &quot;What errand is&quot;">​</a></h1><blockquote><p><strong>Run it there as if it were here.</strong> Same command, same output in your terminal, Ctrl-C included, whether &quot;there&quot; is a container, a server over ssh, a Slurm allocation or a Windows VM. errand sets the place up, syncs the files both ways, and cleans up after itself.</p></blockquote><p>An <em>errand</em> is a trip made on someone&#39;s behalf: go there, do the thing, come back with what it produced.</p><h2 id="who-it-is-for" tabindex="-1">Who it is for <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who it is for&quot;">​</a></h2><p>You write code that computes: research, simulation, HPC, machine learning. It runs on your laptop, on a server or two at the lab, on a national cluster, and now and then on Windows to build a wheel. Each place has its own way in (ssh, <code>module load</code>, <code>sbatch</code>, a container, a conda env), and you know all of them by heart.</p><p>errand is for that work. It is not a production orchestrator (no Kubernetes, no Ansible), and it is not a new test runner.</p><h2 id="stop-babysitting-your-runs" tabindex="-1">Stop babysitting your runs <a class="header-anchor" href="#stop-babysitting-your-runs" aria-label="Permalink to &quot;Stop babysitting your runs&quot;">​</a></h2><p>What errand takes off your hands:</p><ul><li><strong>The way in.</strong> ssh, then the allocation, then the container, then the env: declared once as a <a href="./environments">stack of layers</a>, crossed by one flag, <code>--env cluster</code>.</li><li><strong>Installing over there.</strong> A layer declares what it needs (a Python version, a <code>requirements.txt</code>, a container recipe), and errand installs it where it runs on first use, then updates it when the declaration changes. Nothing to install by hand, errand included. → <a href="./upkeep">Automatic installations</a></li><li><strong>Moving files.</strong> Only what changed crosses, both ways; what a run made over there is never deleted; results and live views come back. → <a href="./sync">Smart sync</a></li><li><strong>Fetching and computing twice.</strong> <code>errand.download</code> and <code>@errand.memo</code> keep data and results in a cache that reaches every machine. → <a href="./caching">Computed once</a></li><li><strong>Looking for results.</strong> <code>errand run -O</code> opens the run&#39;s page in the browser: its console, progress, curves, images and HTML pages, live, wherever it runs. <code>errand web</code> lists every run of every machine with its parameters and results. → <a href="./web">Every run, live in the browser</a></li><li><strong>Watching the connection.</strong> Close the laptop: the work goes on, and <code>errand attach</code> picks it up. → <a href="./detached">Let it run</a></li><li><strong>Paying the start again.</strong> Connections, allocations, VMs and imports are kept warm for a while, so the next command starts faster. → <a href="./agents">Agents</a></li><li><strong>Hunting what was left running.</strong> <code>errand status</code> lists what runs on every machine you sent work to; Ctrl-C stops it through every layer; what a crashed agent left, the next one stops. → <a href="./status">What is running</a></li><li><strong>Taking turns on a machine.</strong> <code>-x</code> keeps the machine to itself for a timing; <code>--cpus</code>, <code>--gpus</code> take a share, and a card is assigned; a run can ask from its own code ( <code>errand.require</code> ). → <a href="./machine">Sharing a machine</a></li></ul><h2 id="you-stay-in-control" tabindex="-1">You stay in control <a class="header-anchor" href="#you-stay-in-control" aria-label="Permalink to &quot;You stay in control&quot;">​</a></h2><p>The usual objection is &quot;I do this by hand, it works, and I don&#39;t want to lose control&quot;. errand hides nothing:</p><ul><li><strong>What runs is your command.</strong> What follows <code>errand run</code> is what you would have typed: <code>make check</code>, <code>python train.py</code>, <code>./bench</code>. errand does not need to know your language.</li><li><strong>You can see every step.</strong> <code>-v</code> prints every command errand starts, including the ssh, the <code>sbatch</code>, the <code>apptainer exec</code> and what it hands to an agent.</li><li><strong>You can get in.</strong> <code>errand shell --env cluster</code> is a real terminal in the allocation, in the container, in the env.</li><li><strong>Nothing is rebuilt behind your back.</strong> An environment that exists the first time errand meets it is adopted as it is. <code>errand setup --dry-run</code> shows what an update would run.</li><li><strong>It is all plain files.</strong> The places are Python, in <code>errand-envs.py</code>. The records are YAML and logs, in <code>errand-outputs/</code>. No database, no daemon to install, no account.</li><li><strong>Nothing to install over there.</strong> errand brings itself to the other machines, and needs nothing but a Python 3.8 or later, which it makes if the machine has none.</li><li><strong>Stop means stop.</strong> Ctrl-C reaches the work wherever it runs. What errand keeps warm stops on its own when unused, and <code>errand agents stop</code> stops it now.</li></ul><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h2><p><strong>Not a scheduler.</strong> <code>Slurm</code> is a layer that asks Slurm for an allocation on your behalf; Slurm decides who gets the nodes. errand only shares out what it was given between your own commands.</p><p><strong>Not a build system.</strong> errand compiles nothing itself. When a run needs a build, it runs the command you already build with.</p><p><strong>Not a replacement for your test runner.</strong> It can run a pytest, Catch2 or cargo suite, one run of its tool per file, in every environment, and <code>pytest</code> keeps working as before. → <a href="./runners/">Running a suite</a></p><p><strong>Not a judge of what compares.</strong> Numbers from a laptop and from a cluster are not comparable, and errand will not stop you. It records where each one came from.</p><h2 id="the-shape-of-a-project" tabindex="-1">The shape of a project <a class="header-anchor" href="#the-shape-of-a-project" aria-label="Permalink to &quot;The shape of a project&quot;">​</a></h2><p>Nothing is required: <code>errand run make</code> works in an empty directory. Once you want to say <em>where</em> things run, files at the project root say it. errand reads every <code>errand-*.py</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>errand-envs.py         the places: versioned when it names no machine   ← errand init</span></span>
<span class="line"><span>errand-project.py      settings, what a bare \`errand run\` runs          ← errand init</span></span>
<span class="line"><span>errand-vars.py         what only this machine knows (hosts, paths): never versioned</span></span>
<span class="line"><span>errand-outputs/        what errand did: runs, builds, bookkeeping</span></span></code></pre></div><p>→ <a href="./configuration">Configuration</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./installing">Installing</a> · <a href="./start">Quickstart</a> · <a href="/errand/tutorials/environments">Four environments</a></p>`,23)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
